function obtenerTextoFormulario(clave) {
    var lang = obtenerIdiomaPreferido();
    var dic = FORMULARIOS_I18N[lang] || FORMULARIOS_I18N['es'];
    return dic[clave] !== undefined ? dic[clave] : FORMULARIOS_I18N['es'][clave];
}

